completion-bash.stdout:
# bash completion for otlv
# Install: otlv completion bash > ~/.local/share/bash-completion/completions/otlv
_otlv() {
    local cur prev cmd
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd="${COMP_WORDS[1]}"

    if [[ $COMP_CWORD -eq 1 ]]; then
        COMPREPLY=( $(compgen -W "dump validate decode encode generate query tag tags diff formats completion --help --version" -- "$cur") )
        return 0
    fi

    case "$cmd" in
        completion)
            if [[ $COMP_CWORD -eq 2 ]]; then
                COMPREPLY=( $(compgen -W "bash zsh fish powershell" -- "$cur") )
                return 0
            fi
            ;;
    esac

    case "$prev" in
        --backend) COMPREPLY=( $(compgen -W "auto streaming document" -- "$cur") ); return 0 ;;
        --output-dir) COMPREPLY=( $(compgen -f -- "$cur") ); return 0 ;;
        --format) COMPREPLY=( $(compgen -W "fixed emv ber der bluetooth-ltv nfc-type2" -- "$cur") ); return 0 ;;
        --input) COMPREPLY=( $(compgen -f -- "$cur") ); return 0 ;;
        --module) COMPREPLY=( $(compgen -W "emv bluetooth" -- "$cur") ); return 0 ;;
        --input-encoding) COMPREPLY=( $(compgen -W "binary hex" -- "$cur") ); return 0 ;;
        --output) COMPREPLY=( $(compgen -W "text json" -- "$cur") ); return 0 ;;
        --output-encoding) case "$cmd" in
            encode) COMPREPLY=( $(compgen -W "binary hex" -- "$cur") ); return 0 ;;
            generate) COMPREPLY=( $(compgen -W "bin json" -- "$cur") ); return 0 ;;
        esac; return 0 ;;
        --emv-context) COMPREPLY=( $(compgen -W "base bit bht bht-format bit-group biometric-counters biometric-attempts biometric-verification" -- "$cur") ); return 0 ;;
        --emv-check) COMPREPLY=( $(compgen -W "structure dictionary all" -- "$cur") ); return 0 ;;
        --output-file) COMPREPLY=( $(compgen -f -- "$cur") ); return 0 ;;
        --diagnostics) COMPREPLY=( $(compgen -W "human compact json" -- "$cur") ); return 0 ;;
        --fixed-byte-order) COMPREPLY=( $(compgen -W "big little" -- "$cur") ); return 0 ;;
    esac

    if [[ "$cur" == -* ]]; then
        case "$cmd" in
            dump) COMPREPLY=( $(compgen -W "--tree --format --input --hex --max-input-size --max-depth --max-elements --pretty --describe --force-color --no-color --module --input-encoding --pdol --decode --output --recover --emv-context --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
            validate) COMPREPLY=( $(compgen -W "--tree --format --input --hex --max-input-size --max-depth --max-elements --pretty --describe --force-color --no-color --module --input-encoding --pdol --decode --output --emv-context --emv-check --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
            decode) COMPREPLY=( $(compgen -W "--format --input --hex --max-input-size --max-depth --max-elements --describe --module --input-encoding --decode --recover --emv-context --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
            encode) COMPREPLY=( $(compgen -W "--format --input --max-input-size --max-depth --max-elements --tag --value --output-encoding --output-file --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
            generate) COMPREPLY=( $(compgen -W "--seed --count --output-dir --max-value-size --max-case-size --format --max-depth --max-elements --output-encoding --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
            query) COMPREPLY=( $(compgen -W "--exists --explain --var --backend --query --count --format --input --hex --max-input-size --max-depth --max-elements --input-encoding --output --value --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
            tag) COMPREPLY=( $(compgen -W "--module --output" -- "$cur") ) ;;
            tags) COMPREPLY=( $(compgen -W "--module --output --search" -- "$cur") ) ;;
            diff) COMPREPLY=( $(compgen -W "--against --where --format --input --max-input-size --max-depth --max-elements --output --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order" -- "$cur") ) ;;
        esac
    fi
}
complete -F _otlv otlv

completion-powershell.stdout:
# PowerShell completion for otlv
# Install: otlv completion powershell >> $PROFILE
Register-ArgumentCompleter -Native -CommandName otlv -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    function Complete-Values([string[]]$Values) {
        $Values | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
            [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
        }
    }
    function Complete-Files() {
        Get-ChildItem -Path "$wordToComplete*" -ErrorAction SilentlyContinue | ForEach-Object {
            [System.Management.Automation.CompletionResult]::new($_.Name, $_.Name, 'ParameterValue', $_.Name)
        }
    }

    $raw = @($commandAst.CommandElements | ForEach-Object { $_.Extent.Text })
    if ($wordToComplete -ne '' -and $raw.Count -gt 0 -and $raw[$raw.Count - 1] -eq $wordToComplete) {
        $raw = @($raw | Select-Object -SkipLast 1)
    }
    $words = @($raw | Select-Object -Skip 1)
    $cmd = if ($words.Count -ge 1) { $words[0] } else { $null }
    $prev = if ($words.Count -ge 1) { $words[$words.Count - 1] } else { $null }

    if (-not $cmd) {
        Complete-Values @('dump validate decode encode generate query tag tags diff formats completion --help --version'.Split(' '))
        return
    }

    switch ($prev) {
        '--backend' { Complete-Values @('auto streaming document'.Split(' ')); return }
        '--output-dir' { Complete-Files; return }
        '--format' { Complete-Values @('fixed emv ber der bluetooth-ltv nfc-type2'.Split(' ')); return }
        '--input' { Complete-Files; return }
        '--module' { Complete-Values @('emv bluetooth'.Split(' ')); return }
        '--input-encoding' { Complete-Values @('binary hex'.Split(' ')); return }
        '--output' { Complete-Values @('text json'.Split(' ')); return }
        '--output-encoding' { switch ($cmd) {
            'encode' { Complete-Values @('binary hex'.Split(' ')); return }
            'generate' { Complete-Values @('bin json'.Split(' ')); return }
        }; return }
        '--emv-context' { Complete-Values @('base bit bht bht-format bit-group biometric-counters biometric-attempts biometric-verification'.Split(' ')); return }
        '--emv-check' { Complete-Values @('structure dictionary all'.Split(' ')); return }
        '--output-file' { Complete-Files; return }
        '--diagnostics' { Complete-Values @('human compact json'.Split(' ')); return }
        '--fixed-byte-order' { Complete-Values @('big little'.Split(' ')); return }
    }

    switch ($cmd) {
        'completion' { if ($words.Count -eq 1) { Complete-Values @('bash zsh fish powershell'.Split(' ')); return } }
    }

    if ($wordToComplete -like '-*') {
        switch ($cmd) {
            'dump' { Complete-Values @('--tree --format --input --hex --max-input-size --max-depth --max-elements --pretty --describe --force-color --no-color --module --input-encoding --pdol --decode --output --recover --emv-context --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
            'validate' { Complete-Values @('--tree --format --input --hex --max-input-size --max-depth --max-elements --pretty --describe --force-color --no-color --module --input-encoding --pdol --decode --output --emv-context --emv-check --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
            'decode' { Complete-Values @('--format --input --hex --max-input-size --max-depth --max-elements --describe --module --input-encoding --decode --recover --emv-context --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
            'encode' { Complete-Values @('--format --input --max-input-size --max-depth --max-elements --tag --value --output-encoding --output-file --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
            'generate' { Complete-Values @('--seed --count --output-dir --max-value-size --max-case-size --format --max-depth --max-elements --output-encoding --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
            'query' { Complete-Values @('--exists --explain --var --backend --query --count --format --input --hex --max-input-size --max-depth --max-elements --input-encoding --output --value --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
            'tag' { Complete-Values @('--module --output'.Split(' ')) }
            'tags' { Complete-Values @('--module --output --search'.Split(' ')) }
            'diff' { Complete-Values @('--against --where --format --input --max-input-size --max-depth --max-elements --output --diagnostics --fixed-tag-size --fixed-length-size --fixed-byte-order'.Split(' ')) }
        }
    }
}
